(function(){
'use strict';
const corpus=window.TypeLayoutCorpus,cases=corpus.slides.concat(corpus.counterexamples),stage=document.querySelector('#stage'),selector=document.querySelector('#scene');
const e=(tag,cls,text)=>{const n=document.createElement(tag);n.className=cls||'';if(text!==undefined)n.textContent=text;return n;};
cases.forEach((s,i)=>{const option=e('option','',String(i+1).padStart(2,'0')+' · '+(Array.isArray(s.title)?s.title.join(' '):s.title));option.value=i;selector.append(option);});
function show(index){const s=cases[index];stage.replaceChildren();stage.classList.toggle('cover',s.layout==='cover');stage.dataset.case=s.id;stage.dataset.align=s.align||'left';const copy=e('header','copy'),title=e('h1','headline');if(Array.isArray(s.title))s.title.forEach(t=>title.append(e('span','',t)));else title.textContent=s.title;title.dataset.editable='true';copy.append(title);const context=e('p','context',s.subtitle);context.dataset.editable='true';copy.append(context);stage.append(copy);if(s.body)stage.append(e('p','prose',s.body));if(s.visual){const result=StageVisual.render(s.visual),body=e('div','chart-body '+(s.visual.composition==='wide'?'wide':''));if(result.hero){const hero=e('div','hero'),number=e('span','hero-value',StageVisual.format(result.hero.value)),unit=e('span','hero-unit',result.hero.unit),label=e('div','hero-label',result.hero.label);const heroLine=e('span','hero-line');heroLine.append(number,unit);hero.append(heroLine,label);body.append(hero);}result.plot.classList.add('plot');body.append(result.plot);stage.append(body);const details=e('details','data-details'),sum=e('summary','','같은 자료의 수치 보기');details.append(sum,StageVisual.tableNode(result.table));if(matchMedia('(max-width:700px)').matches){details.open=true;stage.append(details);}requestAnimationFrame(assess);}stage.append(e('footer','foot','가상 자료 · 실제 성과 아님'));selector.value=index;window.currentCase=index;fit();assess();}
function assess(){const body=stage.querySelector('.chart-body'),hero=stage.querySelector('.hero');if(!body||!hero)return;body.classList.remove('long-value');hero.classList.remove('long-mobile');const line=hero.querySelector('.hero-line');if(line.getBoundingClientRect().width>hero.getBoundingClientRect().width){body.classList.add('long-value');if(innerWidth<700)hero.classList.add('long-mobile');}}
function fit(){const vp=document.querySelector('#viewport');stage.style.transform=innerWidth>700?'scale('+(vp.clientWidth/1600)+')':'';}
selector.addEventListener('change',()=>show(Number(selector.value)));window.addEventListener('resize',()=>{fit();requestAnimationFrame(assess);});stage.addEventListener('input',()=>requestAnimationFrame(assess));document.querySelector('#edit').onclick=()=>{const editing=!stage.classList.contains('editing');stage.classList.toggle('editing',editing);stage.querySelectorAll('[data-editable]').forEach(n=>n.contentEditable=String(editing));};document.querySelector('#replay').onclick=()=>{stage.classList.remove('replaying');requestAnimationFrame(()=>stage.classList.add('replaying'));};window.TypeAShow=show;show(0);
}());
